sys_script_client.script:
function onSubmit() {
    // Perform final validation before form submission
    try {
        // Get form values
        var stockName = g_form.getValue('stock_name');
        var buyingPrice = g_form.getValue('buying_price');
        var stopLoss = g_form.getValue('stop_loss');
        var tradeDate = g_form.getValue('date');

        // Clear any previous error messages
        g_form.clearMessages();

        // Validate required fields
        if (!stockName || stockName.trim() === '') {
            g_form.addErrorMessage('Stock Name is required');
            return false;
        }

        if (!buyingPrice || buyingPrice.trim() === '') {
            g_form.addErrorMessage('Buying Price is required');
            return false;
        }

        if (!stopLoss || stopLoss.trim() === '') {
            g_form.addErrorMessage('Stop Loss is required');
            return false;
        }

        if (!tradeDate || tradeDate.trim() === '') {
            g_form.addErrorMessage('Trade Date is required');
            return false;
        }

        // Validate numeric values
        var buying = parseFloat(buyingPrice);
        var stop = parseFloat(stopLoss);

        if (isNaN(buying) || buying <= 0) {
            g_form.addErrorMessage('Buying Price must be a valid positive number');
            return false;
        }

        if (isNaN(stop) || stop <= 0) {
            g_form.addErrorMessage('Stop Loss must be a valid positive number');
            return false;
        }

        // Validate stop loss is less than buying price
        if (stop >= buying) {
            g_form.addErrorMessage('Stop Loss must be lower than Buying Price');
            return false;
        }

        // Validate risk percentage is reasonable
        var riskPercentage = ((buying - stop) / buying) * 100;
        if (riskPercentage > 25) {
            var confirmMessage = 'This trade has a high risk of ' + riskPercentage.toFixed(1) + '%. ' +
                               'Are you sure you want to proceed with this stop loss?';
            if (!confirm(confirmMessage)) {
                return false;
            }
        }

        // Validate stock name format
        var hasTickerPattern = /\([A-Z]{1,5}\)$/.test(stockName.trim());
        if (!hasTickerPattern) {
            var confirmStockName = 'Stock name does not include ticker symbol in standard format. ' +
                                 'Continue anyway?';
            if (!confirm(confirmStockName)) {
                return false;
            }
        }

        // Validate trade date is not in the future
        var today = new Date();
        var inputDate = new Date(tradeDate);

        if (inputDate > today) {
            var confirmFutureDate = 'Trade date is in the future. Are you sure this is correct?';
            if (!confirm(confirmFutureDate)) {
                return false;
            }
        }

        // Show success message and allow submission
        g_form.addInfoMessage('✅ Trade validation successful. Submitting record...');

        // Log the submission for audit purposes
        console.log('Trade Book submission validated:', {
            stock: stockName,
            buyingPrice: buyingPrice,
            stopLoss: stopLoss,
            risk: riskPercentage.toFixed(2) + '%',
            date: tradeDate
        });

        return true;

    } catch (error) {
        console.error('Error in Trade Book onSubmit validation: ', error);
        g_form.addErrorMessage('An error occurred during form validation. Please check your inputs and try again.');
        return false;
    }
}
